package net.civeira.phylax.features.document.templatevariable.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.templatevariable.domain.TemplateVariable;
import net.civeira.phylax.features.document.templatevariable.domain.event.TemplateVariableEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class TemplateVariableEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<TemplateVariableEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final TemplateVariable entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
